ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--fixture-source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();a.output.mkdir(parents=True);src=a.output/'unaligned-loader.c';include=a.fixture_source.resolve().as_posix();extra=r'''
#undef main
int main(int argc,char**argv){assert(argc==4);unsigned cases=0;for(int cpu=0;cpu<3;cpu++){size_t n;char*original=read_carrier(argv[cpu+1],&n);for(unsigned shift=1;shift<=8;shift++){char*buffer=malloc(n+shift);assert(buffer);memcpy(buffer+shift,original,n);Elf32_Ehdr h;reset();assert(!qdrv_fw_preflight(buffer+shift,n,cpu,&h)&&!maps&&!copies&&!zeros);uint32_t start=0xdeadbeef;assert(qdrv_fw_install(buffer+shift,n,&start,cpu)==h.e_phnum&&start==h.e_entry&&maps==unmaps);free(buffer);cases++;}free(original);}printf("{\"shifted_carrier_cases\":%u,\"preflight_mapping_calls\":0}\n",cases);return 0;}
''';src.write_text('#define main retained_fixture_main\n#include "'+include+'"\n'+extra);compiler=ROOT/'tools/external/llvm-mingw-20260616-ucrt-x86_64/bin/i686-w64-mingw32-clang.exe';binary=a.output/'fixture.exe';r=subprocess.run([str(compiler),'-O1','-std=gnu11','-Wall','-Wextra',str(src),'-o',str(binary)],capture_output=True);(a.output/'compile.log').write_bytes(r.stdout+r.stderr);assert not r.returncode,r.stderr.decode();carriers=[ROOT/'work/hgw500-rootfs-live/squashfs-root/etc/firmware'/n for n in ['qtn_driver.qtn_ruby.0.bin','auc_driver.nomu.0.bin','rdsp_driver.0.bin']];r=subprocess.run([str(binary),*map(str,carriers)],capture_output=True);(a.output/'run.log').write_bytes(r.stdout+r.stderr);assert not r.returncode,r.stderr.decode();proof=json.loads(r.stdout);pins={str(p):sha(p)for p in[Path(__file__),a.fixture_source,src,compiler,binary,*carriers]};result={'status':'PASS_R23_ACTUAL_LOADER_SHIFTED_INPUT_HEADER_PHDR_FWINFO_BUFFER_FIXTURE','hardware_accessed':False,'firmware_eligible':False,**proof,'pins':pins,'limits':'ActualretainedR23preflight/installfunctions on24 shiftedbuffers; fakeaddressmapping/copy/CCM. HostARC32alignment behavioronly, no physical loader or bus execution.'};(a.output/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
